       "type": "code",
       "language": "csharp",
       "dir": "ltr",
       "code": "public static bool What1(int x, int num)\n{\n      if (num == 0)\n            return false;\n      else\n            if (num % 10 == x)\n                  return true;\n            else\n                  return What1(x , num/10);\n}\n\npublic static int What2(int[] a, int k)\n{\n      if (k == (a.Length -1))\n            return 0;\n      else\n            if (What1(a[k] % 10 , a[k+1]) == true)\n                  return 1 + What2 (a , k+1);\n            else\n                  return What2 (a , k +1);\n}",
       "origin": "teacher-enrichment"
