       "dir": "ltr",
       "code": "public static int What1(int[] A, int b, int e)\n{\n    if (b == e) return b;\n    else\n    {\n        int m = (b + e) / 2;\n        int x = What1(A, b, m);\n        int y = What1(A, m + 1, e);\n        if (A[x] > A[y]) return x;\n        return y;\n    }\n}\npublic static void What2(int[] A, int b, int e)\n{\n    if (b == e) return;\n    int i = What1(A, b, e);\n    Swap(A, i, e);\n    What2(A, b, e - 1);\n}\npublic static void Swap(int[] A, int a, int b)\n{\n    int temp = A[a];\n    A[a] = A[b];\n    A[b] = temp;\n}",
       "origin": "teacher-enrichment"
